 */
export class ListProdutosByClinicUseCase {
  constructor(private readonly produtoRepository: IProdutoRepository) {}

  async execute(
    input: ListProdutosByClinicInput,
  ): Promise<ListProdutosByClinicOutput> {
    // Validações de input
    if (!input.clinicId?.trim()) {
      throw new Error("ID da clínica é obrigatório");
